"use client";

import { MenuItem, TextField } from "@mui/material";
import type { SxProps, Theme } from "@mui/material/styles";
import { useMemo } from "react";
import { useQuery, type QueryKey } from "@tanstack/react-query";

import { standardFieldSx } from "@/components/common/FormControls";

export type CommonSelectOption<TValue extends string> = {
  label: string;
  value: TValue;
};

export type CommonSelectFieldProps<TItem, TValue extends string> = {
  disabled?: boolean;
  errorLabel?: string;
  label: string;
  loadingLabel?: string;
  mapOption: (item: TItem) => CommonSelectOption<TValue>;
  onChange: (value: TValue | "") => void;
  placeholder?: string;
  queryFn: () => Promise<readonly TItem[]>;
  queryKey: QueryKey;
  required?: boolean;
  size?: "small" | "medium";
  sortOptions?: (left: CommonSelectOption<TValue>, right: CommonSelectOption<TValue>) => number;
  sx?: SxProps<Theme>;
  value: TValue | "";
};

export function CommonSelectField<TItem, TValue extends string>({
  disabled = false,
  errorLabel = "Failed to load options.",
  label,
  loadingLabel = "Loading...",
  mapOption,
  onChange,
  placeholder = "Select",
  queryFn,
  queryKey,
  required = false,
  size = "small",
  sortOptions,
  sx,
  value,
}: CommonSelectFieldProps<TItem, TValue>) {
  const query = useQuery({
    queryKey,
    queryFn,
  });

  const options = useMemo(() => {
    const mapped = (query.data ?? []).map(mapOption);
    return sortOptions ? [...mapped].sort(sortOptions) : mapped;
  }, [mapOption, query.data, sortOptions]);

  return (
    <TextField
      fullWidth
      label={label}
      onChange={(event) => onChange(event.target.value as TValue | "")}
      select
      size={size}
      sx={sx ?? standardFieldSx}
      value={value}
      disabled={disabled}
      helperText={query.isError ? errorLabel : undefined}
      error={query.isError}
      required={required}
    >
      <MenuItem value="" disabled>
        {placeholder}
      </MenuItem>
      {query.isLoading ? (
        <MenuItem value="" disabled>
          {loadingLabel}
        </MenuItem>
      ) : null}
      {options.map((option) => (
        <MenuItem key={option.value} value={option.value}>
          {option.label}
        </MenuItem>
      ))}
    </TextField>
  );
}
